handler:
() => {
                            const currentLang = localStorage.getItem('bin_language');
                            localStorage.clear();
                            if (currentLang) localStorage.setItem('bin_language', currentLang);
                            signOut(auth).then(() => window.location.href = '/');
                        }

() => act('adminIssuePaintingQuote', {
                    projectId: p.id, priceAed: Number(priceAed),
                    lines: lines.map((l) => ({ ...l, qty: Number(l.qty || 0), unitCostAed: Number(l.unitCostAed || 0), currency: 'AED' })),
                    ...(belowTargetReason.trim() ? { belowTargetReason } : {}),
                    surveyMeasurements: { wallAreaSqm: Number(survey.wallAreaSqm || 0), condition: survey.condition, paintGrade: survey.paintGrade },
                  }, t('Quote issued.', 'تم إصدار العرض.'), `quote_${p.id}`)

() => act('adminAssignPaintingContractor', {
                      projectId: p.id, name: contractor.name, tradeLicenseNo: contractor.tradeLicenseNo || undefined, phone: contractor.phone || undefined,
                      ...(contractor.agreedCostAed ? { agreedCostAed: Number(contractor.agreedCostAed) } : {}),
                    }, t('Contractor assigned.', 'تم تعيين المقاول.'), `contractor_${p.id}`)

async () => {
                      await act('adminRecordPaintingCost', { projectId: p.id, category: costLine.category, amountAed: Number(costLine.amountAed), description: costLine.description, vendor: costLine.vendor || undefined }, t('Cost recorded.', 'تم تسجيل التكلفة.'), `cost_${p.id}`);
                      setCostLine({ category: 'CONTRACTOR', amountAed: '', description: '', vendor: '' });
                    }

() => {
                                            if (onCallClick) onCallClick();
                                            else {
                                                const phone = ticket.assignedTechnicianPhone || ticket.technicianPhone;
                                                openContactUrl(telHref(normalizeContactPhone(phone)));
                                            }
                                        }

() => downloadCsv(
              'bin-roi-by-property.csv',
              ['Property', 'Rent collected (AED)', 'Rent outstanding (AED)', 'Maintenance cost (AED)', 'Collection rate (%)'],
              passports.map((passport: any) => {
                const collected = Number(passport.rentCollectedTotal || 0);
                const outstanding = Number(passport.rentOutstandingTotal || 0);
                const rate = collected + outstanding > 0 ? (collected / (collected + outstanding)) * 100 : 0;
                return [passport.propertyName || passport.id, collected, outstanding, passport.maintenanceCostTotal || 0, rate.toFixed(2)];
              }),
            )
